"""Source Gaussian arithmetic fixtures, independently generated by NumPy 1.26.4.

Each fixture is 1000 RandomState.standard_normal values after the source's
ten-point design without replacement, plus all 1000 cached-Gaussian states.
The modern compiled NumPy normal differs at some last bits on this Mac. The
source-specific scalar operation order must not weaken checkpoint equality.
"""
import hashlib

import numpy as np
import pytest

from basat.environments.Adversarial import _source_mt19937_normal
from basat.workflow import RandomStream


FIXTURES = [
    (4291099476, "956d5b74acf37b95e6131c9eea2d025047b38faf365bffd6ea56eac9506c3586", "1ae7dad0aeeeb4162949008cf60488ea3f09735708035243d07881746a8c280d"),
    (3077295879, "d4ec311d001a7c93d1684ebb8a5fd3288dbe8cdbef6d607541f0dbb3293b2b44", "a2af7d8d168ad1155c2ad58edbfd08a8cc8ede52188b1c6a634c33c285d906ee"),
    (1975078103, "cd45bdd72c6070eb5de0f0edc6292e399e8475e74955e7ba486aae303e8ae739", "1a0da1ec45fa8c35870e2abea1a0a2a763c668acc41d6a3ae32880a5d6802af3"),
    (1018699722, "3ec29ea0330cc04b76f2df2a0298929b942ded09a07c8e1e4cda1e996a419b17", "3005c0e4550403d7db150e69f5e0d3f43634947ec134e25821c882baaa7fb62f"),
    (3397492307, "ac89c150b6fd8e10879d34845f03168b8e938f1ba54356445bee863985ea48b0", "ee9e0ca6af832bc9449554a0016897ff7963959c3239c27fb987a6a1d370d544"),
    (3030081485, "5c4d0e91f8264c0ac97738e103d69b6777173332a45bbbbd5acc9cdb6a963236", "3ee15fbc06354970799a317919335c633c9c11a146efd2b05d97961fe83e92f4"),
    (123, "56531bf757122d8012a79973599f0c5b7398ab1382b3c85cc329225b9e22166b", "35bf2bfdec64e60740c5e5b866d414d483754549a87ba2dbc8fa141cbc61e797"),
]


def digest(values):
    return hashlib.sha256(np.asarray(values, dtype="<f8").tobytes()).hexdigest()


@pytest.mark.parametrize("seed,expected_values,expected_caches", FIXTURES)
def test_old_numpy_scalar_normal_values_and_cached_states(seed, expected_values, expected_caches):
    stream = RandomStream(seed, engine="mt19937")
    stream.choice(1024, size=10, replace=False)
    values, caches = [], []
    for _ in range(1000):
        values.append(_source_mt19937_normal(stream))
        caches.append(stream.get_state()["cached_gaussian"])
    assert digest(values) == expected_values
    assert digest(caches) == expected_caches


def test_cached_normal_checkpoint_restore_consumes_no_additional_uniforms():
    uninterrupted = RandomStream(4291099476, engine="mt19937")
    uninterrupted.choice(1024, size=10, replace=False)
    _source_mt19937_normal(uninterrupted)
    state = uninterrupted.get_state()
    assert state["has_gaussian"] == 1
    resumed = RandomStream(1, engine="mt19937")
    resumed.set_state(state)
    expected = _source_mt19937_normal(uninterrupted)
    actual = _source_mt19937_normal(resumed)
    assert actual == expected == state["cached_gaussian"]
    assert resumed.get_state() == uninterrupted.get_state()
    assert resumed.get_state()["keys"] == state["keys"]
    assert resumed.get_state()["position"] == state["position"]
    assert resumed.get_state()["has_gaussian"] == 0
    assert resumed.get_state()["cached_gaussian"] == 0.


def test_source_scalar_draw_does_not_change_ordinary_randomstream_normal():
    ordinary = RandomStream(123, engine="mt19937")
    expected = np.random.RandomState(123)
    values = [ordinary.normal() for _ in range(100)]
    assert values == expected.normal(size=100).tolist()
